// ============================================================================
// PERSIAN & ENGLISH FUZZY SEARCH NORMALIZER (Handles "جلو باز دمبل", typos, ZWNJ)
// ============================================================================
function normalizeSearchText(raw: string): string {
  if (!raw) return '';
  let s = raw
    .toLowerCase()
    .replace(/[\u200B-\u200D\uFEFF]/g, ' ')
    .replace(/ي/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/ة/g, 'ه')
    .replace(/[آأإ]/g, 'ا')
    .replace(/[-_()/،,]/g, ' ');

  // Normalize common Iranian gym terminology & partial words:
  // e.g. "جلو باز دمبل" -> matches "جلو بازو دمبل"
  s = s.replace(/جلو\s*باز(?!و)/g, 'جلو بازو');
  s = s.replace(/پشت\s*باز(?!و)/g, 'پشت بازو');
  s = s.replace(/جلوبازو/g, 'جلو بازو');
  s = s.replace(/پشتبازو/g, 'پشت بازو');
  s = s.replace(/سیمکش/g, 'سیم کش');
  s = s.replace(/بالاسینه/g, 'بالا سینه');
  s = s.replace(/زیرسینه/g, 'زیر سینه');
  s = s.replace(/زیربغل/g, 'زیر بغل');
  s = s.replace(/سرشانه/g, 'سر شانه');
  s = s.replace(/چهارسر/g, 'چهار سر');
  s = s.replace(/جلوپا/g, 'جلو پا');
  s = s.replace(/پشتپا/g, 'پشت پا');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

