    { id: 'aud-2', actor: 'sohrab.coach@apexfit.io', role: 'COACH', action: 'PROGRAM_ASSIGNED', resource: 'usr-101 -> Hypertrophy Block B', ip: '94.182.11.40', timestamp: '2026-10-21 11:05:44 UTC' },
    { id: 'aud-3', actor: 'kianoush@apexfit.io', role: 'USER', action: '2FA_TOTP_VERIFIED', resource: 'sess-1 (RS256 Token Rotation)', ip: '185.143.232.19', timestamp: '2026-10-21 08:30:02 UTC' },
    { id: 'aud-4', actor: 'system@webhook', role: 'SUPER_ADMIN', action: 'PAYMENT_WEBHOOK_VERIFIED', resource: 'tx_994812_stripe (HMAC-SHA256 OK)', ip: '54.187.205.235', timestamp: '2026-10-20 19:14:55 UTC' }
