  // --------------------------------------------------------------------------
  // LIVE TIMERS (Workout Elapsed, Rest Countdown & Biomechanical Animation)
  // --------------------------------------------------------------------------
  useEffect(() => {
    if (!isWorkoutRunning) return;
    const interval = setInterval(() => {
      setWorkoutElapsedSec((prev) => prev + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, [isWorkoutRunning]);

  useEffect(() => {
    if (restTimerSec <= 0) return;
    const interval = setInterval(() => {
      setRestTimerSec((prev) => Math.max(0, prev - 1));
    }, 1000);
    return () => clearInterval(interval);
  }, [restTimerSec]);

  useEffect(() => {
    const interval = setInterval(() => {
      setAnimPhase((p) => (p === 'concentric' ? 'eccentric' : 'concentric'));
    }, 1800);
    return () => clearInterval(interval);
  }, []);

  // --------------------------------------------------------------------------
  // UNIT CONVERSION & FORMATTING HELPERS
  // --------------------------------------------------------------------------
  const formatWeight = (kg: number) => {
    if (unitSystem === 'IMPERIAL') {
      return `${(kg * 2.20462).toFixed(1)} lb`;
    }
    return `${kg.toFixed(1)} kg`;
  };

  const formatLength = (cm: number) => {
    if (unitSystem === 'IMPERIAL') {
      return `${(cm * 0.393701).toFixed(1)} in`;
    }
    return `${cm.toFixed(1)} cm`;
  };

  const formatDuration = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  };

