  // COMPUTED METRICS (REAL REACTIVE STATE, ZERO HARDCODED TOTALS)
  // --------------------------------------------------------------------------
  const activeWorkout = useMemo(
    () => workouts.find((w) => w.id === selectedWorkoutId) || workouts[0],
    [workouts, selectedWorkoutId]
  );

  const workoutSummary = useMemo(() => {
    let volumeKg = 0;
    let completedSets = 0;
    let totalSets = 0;
    let totalReps = 0;
    activeWorkout.blocks.forEach((b) => {
      b.sets.forEach((s) => {
        totalSets += 1;
        if (s.completed) {
          completedSets += 1;
          totalReps += s.reps;
          volumeKg += s.reps * s.weightKg;
        }
      });
    });
    const calories = Math.round((workoutElapsedSec / 60) * 7.2 + volumeKg * 0.018);
    return { volumeKg, completedSets, totalSets, totalReps, calories };
  }, [activeWorkout, workoutElapsedSec]);

